-- An `ON UPDATE CASCADE` fires once the statement's rows are written, so a later target
-- row's own oversized key outranks the oversized child entry the earlier row's cascade would
-- write, and the refusal names the parent's index.
-- @setup
CREATE TABLE p (k text PRIMARY KEY, v int);
CREATE TABLE c (pad text, k text REFERENCES p ON UPDATE CASCADE);
CREATE INDEX c_i ON c (pad, k);
INSERT INTO p VALUES ('a', 1), ('b', 1);
INSERT INTO c VALUES ('', 'a');
-- @test
-- @expect-error: the second row's key is refused before the cascade runs
-- @expect-message
-- @profile-lock
UPDATE p SET k = CASE WHEN k = 'a' THEN '' ELSE '' END;
